head.script:
scwin.vScrenID = "ULDINF05800.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDINF05800";
scwin.std_cd_grnt_start_dd  = "";
scwin.std_cd_grnt_end_dd	= "";
scwin.searchRadio 		    = "";
scwin.searchRadio1 		    = "";
scwin.isur_cd 			    = "";
scwin.isur_nm 			    = "";
scwin.com_nm 				= "";
scwin.searchDateRadio = 4;
scwin.pageItemCnt = 5;
scwin.pageIndex = 1;
scwin.curDate = WebSquare.date.getCurrentServerDate("yyyyMMdd");  // 서버를 기준으로 현재 날짜 반환

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    /*
    scwin.std_cd_grnt_start_dd  = (request.getAttribute("std_cd_grnt_start_dd").equals(""))?"":request.getAttribute("std_cd_grnt_start_dd");
    scwin.std_cd_grnt_end_dd	= (request.getAttribute("std_cd_grnt_end_dd").equals(""))?"":request.getAttribute("std_cd_grnt_end_dd");
    scwin.searchRadio 		    = (request.getAttribute("searchRadio").equals(""))?"1":request.getAttribute("searchRadio");
    scwin.searchRadio1 		    = request.getAttribute("searchRadio");
    scwin.isur_cd 			    = (request.getAttribute("isur_cd").equals(""))?"":request.getAttribute("isur_cd");
    scwin.isur_nm 			    = (request.getAttribute("isur_nm").equals(""))?"":request.getAttribute("isur_nm");
    scwin.com_nm 				= (request.getAttribute("com_nm").equals(""))?"":request.getAttribute("com_nm");
    */
    btn_downExcel.hide();

    dma_search.set("isurCd", "00003");

    scwin.dateSetting();

    rdo_searchRadio.setValue(1);
    //rdo_searchRadio.setSelectedIndex(0);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// Component Event /////////
scwin.btn_3mon_onclick = function (e) {
    cal_stdCdGrntEndDd.setValue(scwin.curDate);
    cal_stdCdGrntStartDd.setValue($c.date.addDate(scwin.curDate, -90));
};

scwin.btn_6mon_onclick = function (e) {
    cal_stdCdGrntEndDd.setValue(scwin.curDate);
    cal_stdCdGrntStartDd.setValue($c.date.addDate(scwin.curDate, -181));	
};

scwin.btn_1year_onclick = function (e) {
    cal_stdCdGrntEndDd.setValue(scwin.curDate);
    cal_stdCdGrntStartDd.setValue($c.date.addDate(scwin.curDate, -365));
};

scwin.pgl_pageList_onviewchange = function (info) {
    scwin.pageIndex = info.newSelectedIndex;
    scwin.search(info.newSelectedIndex);
    pgl_pageList.setSelectedIndex(info.newSelectedIndex);	
};

scwin.ibx_isurNm_oneditenter = function (e) {
	scwin.search('1');
};

scwin.btn_search_onclick = function (e) {
    scwin.search('1');	
};

scwin.rdo_searchRadio_onviewchange = function (info) {
    const value = info.value;
    if(value === 10 || value === 11) {
        btn_downExcel.show();
    } else {
        btn_downExcel.hide();
    }
};

scwin.btn_downExcel_onclick = function (e) {

};

scwin.grd_dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    let mktNm = dlt_main.getCellData(rowIndex, "mktNm");

    if(columnId === "stdCd") {
        if (mktNm !== "14" && mktNm !== "15" && mktNm !== "17") {
            let url = "";
            let popTitle = "";

            if(mktNm === "1") {

            } else if (mktNm === "2") {
                url = "/ui/inf/ULDINF91000.xml";
                popTitle = "주권 상세정보";
            } else if (mktNm === "3") {
                url = "/ui/inf/ULDINF91100.xml";
                popTitle = "채권 상세정보";
            } else if (mktNm === "4") {
                url = "/ui/inf/ULDINF91400.xml";
                popTitle = "수익증권 상세정보";
            } else if (mktNm === "5") {
                url = "/ui/inf/ULDINF91500.xml";
                popTitle = "신주인수권증권 상세정보";
            } else if (mktNm === "55") {
                url = "/ui/inf/ULDINF91600.xml";
                popTitle = "신주인수권증서 상세정보";
            } else if (mktNm === "6") {
                url = "/ui/inf/ULDINF91800.xml";
                popTitle = "양도성예금증서(CD) 상세정보";
            } else if (mktNm === "7") {
                url = "/ui/inf/ULDINF92000.xml";
                popTitle = "CP 상세정보";
            } else if (mktNm === "77") {
                url = "/ui/inf/ULDINF91900.xml";
                popTitle = "전자단기사채 상세정보";
            } else if (mktNm === "8") {
                url = "/ui/inf/ULDINF92100.xml";
                popTitle = "유가증권예탁증서(DR) 상세정보";
            } else if (mktNm === "9") {
                url = "/ui/inf/ULDINF92300.xml";
                popTitle = "스트립 상세정보";
            } else if (mktNm === "101") {
                url = "/ui/inf/ULDINF91200.xml";
                popTitle = "ELS/DLS/ELB/DLB 상세정보";
            } else if (mktNm === "102") {
                url = "/ui/inf/ULDINF91200.xml";
                popTitle = "ELS/DLS/ELB/DLB 상세정보";
            } else if (mktNm === "103") {
                url = "/ui/inf/ULDINF91200.xml";
                popTitle = "ELS/DLS/ELB/DLB 상세정보";
            } else if (mktNm === "104") {
                url = "/ui/inf/ULDINF91200.xml";
                popTitle = "ELS/DLS/ELB/DLB 상세정보";
            } else if (mktNm === "11") {
                url = "/ui/inf/ULDINF91700.xml";
                popTitle = "주식워런트(ELW) 상세정보";
            } else if (mktNm === "12" || mktNm === "122") {
                url = "/ui/inf/ULDINF91300.xml";
                popTitle = "선물옵션 상세정보";
            } else if (mktNm === "13") {
                url = "/ui/inf/ULDINF92200.xml";
                popTitle = "지표 상세정보";
            } else if (mktNm === "14" || mktNm === "16") {
                url = "/ui/inf/ULDINF92400.xml";
                popTitle = "ETN 상세정보";
            } else if (mktNm === "15" || mktNm === "18") {
                url = "/ui/inf/ULDINF92500.xml";
                popTitle = "투자계약증권 상세정보";
            }
            /*
            else if (mktNm == "16") {
                dlt_main.setCellData(i, "mktNm2", "ETN");
            } else if (mktNm == "17") {
                dlt_main.setCellData(i, "mktNm2", "배출권");
            } else if (mktNm == "18") {
                dlt_main.setCellData(i, "mktNm2", "투자계약증권");
            }
            */
            const param = {
                mktNm : dlt_main.getCellData(rowIndex, "mktNm"),
                stdCd : dlt_main.getCellData(rowIndex, "stdCd"),
                modifyYn : "Y"
            };
            const opts = {
                id: "",
                popupName: popTitle,
                width: 900,
                height: 679,
                frameModal: "top",
            };
            //var rtn = await $c.win.openPopup(url, opts, param);
            $c.win.openPopup(url, opts, param);
        }
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// Submission 처리///////// 
scwin.sbm_search_submitdone = function (e) {

    const totalCount = e.responseJSON.body.totalCount;
    const tatalPage = $c.num.ceil(totalCount / scwin.pageItemCnt);
    panel_page.setValue(totalCount);
    pgl_pageList.setCount(tatalPage);
    pgl_pageList.setSelectedIndex(scwin.pageIndex);

    for(let i = 0; i < dlt_main.getRowCount(); i++) {
        let mktNm = dlt_main.getCellData(i, "mktNm");
        const listStatCd = dlt_main.getCellData(i, "listStatCd");

        if(mktNm === "1") {

        } else if (mktNm === "2") {
            dlt_main.setCellData(i, "mktNm2", "주권");
        } else if (mktNm === "3") {
            dlt_main.setCellData(i, "mktNm2", "채권");
        } else if (mktNm === "4") {
            dlt_main.setCellData(i, "mktNm2", "수익증권");
        } else if (mktNm === "5") {
            dlt_main.setCellData(i, "mktNm2", "신주인수권증권");
        } else if (mktNm === "55") {
            dlt_main.setCellData(i, "mktNm2", "신주인수권증서");
        } else if (mktNm === "6") {
            dlt_main.setCellData(i, "mktNm2", "CD");
        } else if (mktNm === "7") {
            dlt_main.setCellData(i, "mktNm2", "CP");
        } else if (mktNm === "77") {
            dlt_main.setCellData(i, "mktNm2", "전자단기사채");
        } else if (mktNm === "8") {
            dlt_main.setCellData(i, "mktNm2", "예탁증서");
        } else if (mktNm === "9") {
            dlt_main.setCellData(i, "mktNm2", "스트립")            
        } else if (mktNm === "101") {
            dlt_main.setCellData(i, "mktNm2", "ELS");            
        } else if (mktNm === "102") {
            dlt_main.setCellData(i, "mktNm2", "DLS");
        } else if (mktNm === "103") {
            dlt_main.setCellData(i, "mktNm2", "ELB");
        } else if (mktNm === "104") {
            dlt_main.setCellData(i, "mktNm2", "DLB");
        } else if (mktNm === "11") {
            dlt_main.setCellData(i, "mktNm2", "주식워런트");
        } else if (mktNm === "12") {
            dlt_main.setCellData(i, "mktNm2", "선물/옵션");
        } else if (mktNm === "16") {
            dlt_main.setCellData(i, "mktNm2", "ETN");
        } else if (mktNm === "18") {
            dlt_main.setCellData(i, "mktNm2", "투자계약증권");
        }

        if(listStatCd === "Y") {
            dlt_main.setCellData(i, "listStatNm", "상장");
        } else if(listStatCd === "N" || listStatCd === "-") {
            dlt_main.setCellData(i, "listStatNm", "비상장");
        } else if(listStatCd === "D") {
            dlt_main.setCellData(i, "listStatNm", "상장폐지");
        } else if(listStatCd === "I") {
            dlt_main.setCellData(i, "listStatNm", "미발행");
        } else if(listStatCd === "Z") {
            dlt_main.setCellData(i, "listStatNm", "기타");
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
///////// Function /////////
scwin.dateSetting = function () {
	//console.log('dateSetting');
	const curDate = scwin.curDate;
	const curYY = curDate.substring(0,4);
	const curMM = curDate.substring(4,6);
	const curDD = curDate.substring(6,8);

	const intCurYY = Number(curYY);
	const intCurMM = Number(curMM);

	let bfOneYY = "";
	let bfOneMM = "";
	//1년전
	let calMM = intCurMM-12;
	if ( calMM<0 )
	{
		bfOneYY = intCurYY-1;
		bfOneMM = 12+calMM;
	} else {
		bfOneYY = intCurYY;
		bfOneMM = calMM;
	}

	let bfThreeYY = "";
	let bfThreeMM = "";
	//3개월전
	let calMM = intCurMM-3;
	if ( calMM<0 )
	{
		bfThreeYY = intCurYY-1;
		bfThreeMM = 12+calMM;
	} else {
		bfThreeYY = intCurYY;
		bfThreeMM = calMM;
	}

	let bfSixYY = "";
	let bfSixMM = "";
	//6개월전
	let calMM = intCurMM-6;
	if ( calMM<0 )
	{
		bfSixYY = intCurYY-1;
		bfSixMM = 12+calMM;
	} else {
		bfSixYY = intCurYY;
		bfSixMM = calMM;
	}

	const oneDD = new Date(bfOneYY,bfOneMM,curDD);
	const threeDD = new Date(bfThreeYY,bfThreeMM,curDD);
	const sixDD = new Date(bfSixYY,bfSixMM,curDD);

	if ( Number(bfOneMM)<10) bfOneMM="0"+bfOneMM;	
	if ( Number(bfThreeMM)<10) bfThreeMM="0"+bfThreeMM;
	if ( Number(bfSixMM)<10) bfSixMM="0"+bfSixMM;

	const oneD = ( Number(oneDD.getMonth())<10)?("0"+oneDD.getMonth()):oneDD.getMonth();	
	const ThD = ( Number(threeDD.getMonth())<10)?("0"+threeDD.getMonth()):threeDD.getMonth();
	const SxD = ( Number(sixDD.getMonth())<10)?("0"+sixDD.getMonth()):sixDD.getMonth();

	const oneDt = ( Number(oneDD.getDate())<10)?("0"+oneDD.getDate()):oneDD.getDate();	
	const ThDt = ( Number(threeDD.getDate())<10)?("0"+threeDD.getDate()):threeDD.getDate();
	const SxDt = ( Number(sixDD.getDate())<10)?("0"+sixDD.getDate()):sixDD.getDate();

	const bfOneDate = oneDD.getFullYear()+oneD+oneDt;
	const bfThreeDate = threeDD.getFullYear()+ThD+ThDt;
	const bfSixDate = sixDD.getFullYear()+SxD+SxDt;

    scwin.hd_oneDate = bfOneDate;
    scwin.hd_threeDate = bfThreeDate;
    scwin.hd_sixDate = bfSixDate;

}

scwin.search = async function (idx) {
    dma_search.set("page", idx);
    dma_search.set("size", scwin.pageItemCnt);
    dma_search.set("searchDateRadio", scwin.searchDateRadio);

    const sbmOptions = {
        id : "sbm_search",
        action : "/api/isin/search/corpStdCd/corpStdCd-select-paging",
        method : "get",
        ref : "dma_search",
        target : "dlt_main=body.content",
        gridview : "grd_dataTb",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.sbm_search_submitdone(sbmRtn);
}
